def count_battleships(board):
    total = 0
    for row in range(len(board)):
        for col in range(len(board[0])):
            if board[row][col]=='X' and (row==0 or board[row-1][col]!='X') and (col==0 or board[row][col-1]!='X'):
                total += 1
    return total

